def skill():
    ks = [k for k in range(-60, 80) if (k - 16 < 0) and (k > 0)]
    return sum(ks)

def standard():
    x = Symbol('x')
    tot = 0
    for k in range(-60, 80):
        f = x**2 - 8*x + k
        pts = [Integer(0), Integer(6)]
        for r in solve(f, x):
            if r.is_real and 0 < r < 6:
                pts.append(r)
        pts = sorted(pts, key=lambda v: float(v))
        absint = 0
        for lo, hi in zip(pts[:-1], pts[1:]):
            mid = (lo + hi)/2
            val = integrate(f, (x, lo, hi))
            absint += val if f.subs(x, mid) >= 0 else -val
        total = integrate(f, (x, 0, 6))
        if abs(N(absint - abs(total), 30)) > 1e-12:
            tot += k
    return tot

def unique():
    return [standard()]
